# Чтение: дивиденды — счёт 3040 (обороты и сальдо по участникам), объявление (Кт3040), налог у источника.
PL = ib.Метаданные.РегистрыБухгалтерии.Получить(0).ПланСчетов.Имя
print("3040 =", s(q(f'ВЫБРАТЬ С.Ссылка КАК С ИЗ ПланСчетов.{PL} КАК С ГДЕ С.Код = "3040"')[0]["С"]))
for r in q("""ВЫБРАТЬ Т.Период КАК П, Т.Регистратор КАК Р, Т.СчетДт.Код КАК Д, Т.СчетКт.Код КАК К, Т.СубконтоДт1 КАК Д1, Т.СубконтоКт1 КАК К1, Т.Сумма КАК С
ИЗ РегистрБухгалтерии.{REG}.ДвиженияССубконто(&Н, &К, СчетДт.Код = "3040" ИЛИ СчетКт.Код = "3040") КАК Т УПОРЯДОЧИТЬ ПО Т.Период""",
           Н=datetime.datetime(2024, 12, 1), К=datetime.datetime(2026, 10, 31)):
    print(f"  {str(r['П'])[:10]} {s(r['Р'])[:50]:<50} {r['Д']}>{r['К']} | {s(r['Д1'])[:24]:<24} | {s(r['К1'])[:24]:<24} | {r['С']:>15,.2f}")
for r in q("""ВЫБРАТЬ Т.Субконто1 КАК С1, Т.СуммаОстатокДт - Т.СуммаОстатокКт КАК Б ИЗ РегистрБухгалтерии.{REG}.Остатки(&Д, Счет.Код = "3040", , ) КАК Т""", Д=datetime.datetime(2026, 10, 31)):
    print("САЛЬДО 3040:", s(r["С1"]), f"{r['Б']:,.2f}")
